+// @vitest-environment jsdom
+import { describe, it, expect, vi, afterEach, beforeEach } from 'vitest';
+import { createElement, type ReactNode } from 'react';
+import { disegna } from './aiuti/cabina-admin';
+
+/**
+ * R33-003 — Gli avvisi sui soldi da sistemare a mano si vedono dentro il pannello.
+ *
+ * `notifyAdmins` scrive solo nella campanella, e la campanella del pannello porta a
+ * /notifications, fuori dal pannello. Il cruscotto «Today», dove l'amministratore atterra,
+ * mostra le sue notifiche non lette che portano a una pagina /admin: titolo, testo e link.
+ */
+
+type Domanda = { tabella: string; filtri: Array<[string, string, unknown]>; ordine: unknown[]; limite: number | null };
+const stato = vi.hoisted(() => ({
+  admin: '00000000-0000-4000-8000-0000000000ad',
+  domande: [] as Array<{ tabella: string; filtri: Array<[string, string, unknown]>; ordine: unknown[]; limite: number | null }>,
+  righe: [] as unknown[],
+  errore: null as unknown,
+}));
+const ADMIN = stato.admin;
+
+vi.mock('@/lib/supabase/client', () => {
+  const from = (tabella: string) => {
+    const q: Domanda = { tabella, filtri: [], ordine: [], limite: null };
+    const b: Record<string, unknown> = {};
+    const filtro = (op: string) => (c: string, v: unknown) => { q.filtri.push([op, c, v]); return b; };
+    Object.assign(b, {
+      select: () => b,
+      eq: filtro('eq'),
+      neq: filtro('neq'),
+      like: filtro('like'),
+      ilike: filtro('ilike'),
+      is: filtro('is'),
+      in: filtro('in'),
+      order: (...a: unknown[]) => { q.ordine.push(a); return b; },
+      limit: (n: number) => { q.limite = n; return b; },
+      then: (ok: (r: unknown) => unknown, ko: (e: unknown) => unknown) => {
+        stato.domande.push(q);
+        return Promise.resolve({ data: stato.errore ? null : stato.righe, error: stato.errore }).then(ok, ko);
+      },
+    });
+    return b;
+  };
+  return {
+    supabase: {
+      from,
+      auth: {
+        getUser: async () => ({ data: { user: { id: stato.admin } } }),
+        getSession: async () => ({ data: { session: null } }),
+        onAuthStateChange: () => ({ data: { subscription: { unsubscribe: () => {} } } }),
+      },
+    },
+  };
+});
+vi.mock('next/link', () => ({ default: ({ href, children }: { href: string; children?: ReactNode }) => createElement('a', { href }, children) }));
+vi.mock('next-intl', () => ({ useTranslations: () => (k: string) => k, useLocale: () => 'it' }));
+vi.mock('@/lib/queries/cruscotto-oggi', async (orig) => ({
+  ...(await orig<Record<string, unknown>>()),
+  leggiCruscottoOggi: async () => ({
+    ordersTodayCount: 0, gmvToday: 0, deliveredToday: 0, ordersPendingCount: 0, ordersProblemCount: 0,
+    sellersPendingCount: 0, sosActiveCount: 0, disputesOpenCount: 0, signupsTodayCount: 0, recentOrders: [],
+    finestraOrdiniRecentiGiorni: 7, campione: false,
+  }),
+}));
+
+let chiudi: (() => void) | null = null;
+beforeEach(() => {
+  vi.useFakeTimers({ toFake: ['Date'] });
+  vi.setSystemTime(new Date('2026-11-17T10:00:00Z'));
+  stato.domande.length = 0;
+  stato.righe = [];
+  stato.errore = null;
+});
+afterEach(() => {
+  chiudi?.();
+  chiudi = null;
+  vi.useRealTimers();
+});
+
+async function apriToday() {
+  const mod = (await import('@/app/admin/today/page')) as { default: () => ReactNode };
+  const r = await disegna(createElement(mod.default));
+  chiudi = r.chiudi;
+  return r.host;
+}
+
+describe('R33-003 — «Avvisi da gestire» nel cruscotto Today', () => {
+  it('mostra titolo, testo e link degli avvisi non letti che portano al pannello', async () => {
+    stato.righe = [
+      {
+        id: 'n1', title: 'Credito MyCity non restituito', body: 'Ordine #ABC123: 5,00 € vanno restituiti a mano.',
+        link: '/admin/orders/abc123', created_at: '2026-11-17T09:30:00Z',
+      },
+      {
+        id: 'n2', title: 'Storno al venditore non riuscito', body: 'Vanno recuperati a mano 12,00 €.',
+        link: '/admin/payouts', created_at: '2026-11-17T08:00:00Z',
+      },
+    ];
+    const host = await apriToday();
+    expect(host.textContent).toMatch(/Avvisi da gestire/);
+    expect(host.textContent).toMatch(/Credito MyCity non restituito/);
+    expect(host.textContent).toMatch(/vanno restituiti a mano/);
+    expect(host.querySelector('a[href="/admin/orders/abc123"]')?.textContent).toMatch(/Credito MyCity non restituito/);
+    expect(host.querySelector('a[href="/admin/payouts"]')?.textContent).toMatch(/Storno al venditore/);
+  });
+
+  it('legge solo le notifiche non lette di questo amministratore con link /admin, le ultime 10', async () => {
+    stato.righe = [{ id: 'n1', title: 'Avviso', body: null, link: '/admin/orders', created_at: '2026-11-17T09:30:00Z' }];
+    await apriToday();
+    const d = stato.domande.find((q) => q.tabella === 'notifications');
+    expect(d, 'il cruscotto non legge le notifiche').toBeTruthy();
+    expect(d!.filtri).toContainEqual(['eq', 'user_id', ADMIN]);
+    expect(d!.filtri).toContainEqual(['eq', 'is_read', false]);
+    expect(d!.filtri).toContainEqual(['like', 'link', '/admin%']);
+    expect(d!.ordine).toContainEqual(['created_at', { ascending: false }]);
+    expect(d!.limite).toBe(10);
+  });
+
+  it('senza avvisi il riquadro non c è; se la lettura cade lo dice invece di tacere', async () => {
+    let host = await apriToday();
+    expect(host.textContent).not.toMatch(/Avvisi da gestire/);
+    chiudi?.();
+    chiudi = null;
+
+    stato.errore = { message: 'rete caduta' };
+    host = await apriToday();
+    expect(host.textContent).toMatch(/Non sono riuscito a leggere gli avvisi da gestire/);
+  });
+});

