new file mode 100644
index 00000000..e13b3ba1
--- /dev/null
+++ b/migrations/571_le_notifiche_push_si_prendono_in_carico_una_volta.sql
@@ -0,0 +1,68 @@
+-- =============================================================================
+-- 571 — Le notifiche push si prendono in carico una volta sola (R33-005)
+-- =============================================================================
+--
+-- Il giro /api/cron/send-push (ogni 5 minuti, fino a 300 secondi) leggeva le
+-- notifiche con `pushed_at` vuoto e le segnava solo a fine giro, dopo gli
+-- invii. Due giri che si sovrappongono (uno lento, uno lanciato a mano, un
+-- nuovo tentativo di Vercel) leggevano le stesse righe e mandavano la stessa
+-- push due volte.
+--
+-- Come la coda delle email (`claim_pending_emails`, migrazioni 085/150/165):
+--   ① una colonna `push_claimed_at`: chi l'ha presa e quando;
+--   ② `claim_pending_push`: sceglie e prende le righe nello stesso comando
+--      (FOR UPDATE SKIP LOCKED, poi UPDATE … RETURNING). Un secondo giro salta
+--      le righe prese da un altro, anche mentre il primo sta ancora mandando.
+--      Le notifiche che non possono aspettare (ordini, avvisi di servizio)
+--      vengono prima di promozioni, gruppi e newsletter: con cento promozioni
+--      piu' vecchie in coda la notifica del nuovo ordine entra comunque nel giro.
+--      Una presa vale 10 minuti, piu' dei 300 secondi di un giro: se il giro
+--      muore a meta', le righe tornano disponibili da sole. Le righe prese e non
+--      mandate (guasto passeggero, preferenza non letta) il giro le rilascia
+--      alla fine, e il giro dopo le riprova come prima.
+--
+-- Permessi: la funzione gira coi permessi di chi la chiama (non SECURITY
+-- DEFINER). EXECUTE solo a service_role (il giro usa la chiave di servizio);
+-- tolto a PUBLIC, anon e authenticated.
+--
+-- Idempotente: si puo' rieseguire.
+-- =============================================================================
+
+-- ① Chi l'ha presa e quando
+ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS push_claimed_at timestamptz;
+
+-- ② La presa in carico atomica
+CREATE OR REPLACE FUNCTION public.claim_pending_push(p_since timestamptz, p_max int DEFAULT 100)
+RETURNS TABLE (id uuid, user_id uuid, title text, body text, link text, category text)
+LANGUAGE plpgsql
+SET search_path = public
+AS $$
+BEGIN
+    RETURN QUERY
+    WITH picked AS (
+        SELECT n.id
+        FROM public.notifications n
+        WHERE n.pushed_at IS NULL
+          AND n.created_at >= p_since
+          AND (n.push_claimed_at IS NULL OR n.push_claimed_at < now() - interval '10 minutes')
+        ORDER BY (n.category IN ('promo', 'group', 'newsletter')), n.created_at
+        LIMIT greatest(coalesce(p_max, 100), 0)
+        FOR UPDATE SKIP LOCKED
+    ),
+    claimed AS (
+        UPDATE public.notifications n
+        SET push_claimed_at = now()
+        FROM picked
+        WHERE n.id = picked.id
+        RETURNING n.id, n.user_id, n.title, n.body, n.link, n.category, n.created_at
+    )
+    SELECT c.id, c.user_id, c.title, c.body, c.link, c.category
+    FROM claimed c
+    ORDER BY (c.category IN ('promo', 'group', 'newsletter')), c.created_at;
+END;
+$$;
+
+REVOKE EXECUTE ON FUNCTION public.claim_pending_push(timestamptz, int) FROM PUBLIC, anon, authenticated;
+GRANT EXECUTE ON FUNCTION public.claim_pending_push(timestamptz, int) TO service_role;
+
+NOTIFY pgrst, 'reload schema';
diff --git a/tests/sql/rls/riparazione-r33-push-presa.test.sql b/tests/sql/rls/riparazione-r33-push-presa.test.sql
