index 00000000..c227ea47
--- /dev/null
+++ b/tests/sql/rls/riparazione-r33-push-presa.test.sql
@@ -0,0 +1,133 @@
+-- =============================================================================
+-- R33-005 — Una notifica push la prende in carico un giro solo
+-- =============================================================================
+-- Gira contro un database ricostruito dalle migrazioni vere:
+--   tests/sql/harness/apply.sh mycity_test
+--   tests/sql/harness/run.sh   mycity_test
+--
+-- Il giro /api/cron/send-push leggeva le notifiche con pushed_at vuoto e le
+-- segnava solo a fine giro: due giri sovrapposti leggevano le stesse righe e
+-- mandavano la stessa push due volte. Con la presa in carico (migrazione 571)
+-- il secondo giro non riprende le righe del primo; ordini e avvisi passano
+-- davanti alle promozioni; una presa scaduta (giro morto a meta') torna libera.
+--
+-- Senza la 571 la prova fa quello che faceva la rotta (la lettura semplice) ed
+-- e' ROSSA: il secondo giro riprende le stesse righe.
+-- Tutto in transazione, ROLLBACK.
+-- =============================================================================
+
+BEGIN;
+
+SET LOCAL mycity.allow_profile_write = '1';
+
+CREATE TEMP TABLE esiti (nome text, ok boolean, dettaglio text) ON COMMIT DROP;
+CREATE TEMP TABLE giri (giro text, id uuid, category text) ON COMMIT DROP;
+GRANT ALL ON esiti, giri TO anon, authenticated, service_role;
+
+INSERT INTO auth.users (id, email, raw_user_meta_data) VALUES
+  ('d3300000-0000-0000-0000-000000000001', 'cliente-r33-push@test.it', '{"role":"buyer"}');
+
+-- Cento promozioni di mezz'ora fa, poi il nuovo ordine di un minuto fa: tutte da mandare.
+INSERT INTO public.notifications (id, user_id, title, body, link, category, created_at)
+SELECT gen_random_uuid(), 'd3300000-0000-0000-0000-000000000001', 'Sconto ' || g, NULL, NULL, 'promo',
+       now() - interval '30 minutes' + g * interval '1 second'
+  FROM generate_series(1, 100) AS g;
+INSERT INTO public.notifications (id, user_id, title, body, link, category, created_at) VALUES
+  ('d3300000-0000-0000-0000-0000000000a1', 'd3300000-0000-0000-0000-000000000001', 'Nuovo ordine', NULL,
+   '/orders/d3300000-0000-0000-0000-0000000000f1', 'order', now() - interval '1 minute');
+
+-- Un giro, come lo fa la rotta: la presa in carico se c'e', se no la lettura di prima.
+CREATE OR REPLACE FUNCTION pg_temp.un_giro(p_giro text) RETURNS void
+LANGUAGE plpgsql AS $$
+BEGIN
+  IF to_regprocedure('public.claim_pending_push(timestamptz,integer)') IS NOT NULL THEN
+    EXECUTE 'INSERT INTO giri SELECT $1, c.id, c.category FROM public.claim_pending_push(now() - interval ''1 hour'', 100) c'
+      USING p_giro;
+  ELSE
+    INSERT INTO giri
+    SELECT p_giro, n.id, n.category
+      FROM public.notifications n
+     WHERE n.pushed_at IS NULL AND n.created_at >= now() - interval '1 hour'
+     ORDER BY n.created_at
+     LIMIT 100;
+  END IF;
+END;
+$$;
+
+SET LOCAL ROLE service_role;
+SELECT pg_temp.un_giro('A');
+SELECT pg_temp.un_giro('B');
+RESET ROLE;
+
+INSERT INTO esiti
+SELECT 'il primo giro prende cento notifiche', count(*) = 100, 'prese dal giro A: ' || count(*)
+  FROM giri WHERE giro = 'A';
+
+INSERT INTO esiti
+SELECT 'il nuovo ordine entra nel primo giro, davanti alle promozioni',
+       bool_or(id = 'd3300000-0000-0000-0000-0000000000a1'),
+       'ordine nel giro A: ' || coalesce(bool_or(id = 'd3300000-0000-0000-0000-0000000000a1'), false)
+  FROM giri WHERE giro = 'A';
+
+INSERT INTO esiti
+SELECT 'il secondo giro non riprende nessuna notifica del primo', count(*) = 0,
+       'notifiche prese da tutti e due i giri: ' || count(*)
+  FROM giri a JOIN giri b ON a.id = b.id AND a.giro = 'A' AND b.giro = 'B';
+
+INSERT INTO esiti
+SELECT 'il secondo giro prende solo quella rimasta fuori', count(*) = 1, 'prese dal giro B: ' || count(*)
+  FROM giri WHERE giro = 'B';
+
+-- Un giro morto a meta': la sua presa, vecchia di 11 minuti, torna libera; quelle fresche no.
+DO $$
+BEGIN
+  IF EXISTS (SELECT 1 FROM information_schema.columns
+              WHERE table_schema = 'public' AND table_name = 'notifications' AND column_name = 'push_claimed_at') THEN
+    EXECUTE 'UPDATE public.notifications SET push_claimed_at = now() - interval ''11 minutes'' WHERE id = $1'
+      USING 'd3300000-0000-0000-0000-0000000000a1'::uuid;
+  END IF;
+END $$;
+SET LOCAL ROLE service_role;
+SELECT pg_temp.un_giro('C');
+RESET ROLE;
+
+INSERT INTO esiti
+SELECT 'una presa scaduta torna libera, le altre restano del loro giro',
+       count(*) = 1 AND bool_and(id = 'd3300000-0000-0000-0000-0000000000a1'),
+       'prese dal giro C: ' || count(*)
+  FROM giri WHERE giro = 'C';
+
+-- Chi ha l'account non prende in carico le notifiche degli altri.
+SET LOCAL ROLE authenticated;
+SET LOCAL request.jwt.claims = '{"sub":"d3300000-0000-0000-0000-000000000001","role":"authenticated"}';
+DO $$
+DECLARE rifiutato boolean := false;
+BEGIN
+  IF to_regprocedure('public.claim_pending_push(timestamptz,integer)') IS NOT NULL THEN
+    BEGIN
+      EXECUTE 'SELECT count(*) FROM public.claim_pending_push(now() - interval ''1 hour'', 100)';
+    EXCEPTION WHEN insufficient_privilege THEN rifiutato := true;
+    END;
+    INSERT INTO esiti VALUES ('chi ha l account non chiama la presa in carico', rifiutato, 'rifiutato: ' || rifiutato);
+  END IF;
+END $$;
+RESET ROLE;
+
+-- ── Verdetto ──────────────────────────────────────────────────────────────
+SELECT nome, CASE WHEN ok THEN 'ok' ELSE 'ROTTO' END AS esito, dettaglio
+  FROM esiti ORDER BY nome;
+
+DO $$
+DECLARE rossi int; elenco text;
+BEGIN
+  SELECT count(*), coalesce(string_agg(format('%s → %s', e.nome, e.dettaglio), E'\n  '), '')
+    INTO rossi, elenco
+  FROM esiti e WHERE e.ok IS NOT TRUE;
+
+  IF rossi > 0 THEN
+    RAISE EXCEPTION E'% controllo/i rosso/i sulla presa in carico delle push:\n  %', rossi, elenco;
+  END IF;
+  RAISE NOTICE 'una notifica push la prende un giro solo: % controlli verdi', (SELECT count(*) FROM esiti);
+END $$;
+
+ROLLBACK;
