@@ -0,0 +1,142 @@
+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
+
+/**
+ * R33-005 — Due giri del cron send-push che si sovrappongono non mandano la stessa push due volte.
+ *
+ * Il finto database tiene le notifiche in memoria. Sa fare la lettura di prima (pushed_at vuoto,
+ * dalla più vecchia) e la presa in carico `claim_pending_push` della migrazione 571 (sceglie e
+ * prende nello stesso passo, salta le righe prese da meno di 10 minuti, ordini prima delle
+ * promozioni). Gli invii aspettano un giro dell'event loop, come una chiamata di rete: così i due
+ * giri si accavallano davvero.
+ */
+
+type Riga = {
+  id: string; user_id: string; title: string; body: string | null; link: string | null; category: string;
+  created_at: string; pushed_at: string | null; push_claimed_at: string | null;
+};
+
+const db = vi.hoisted(() => ({
+  righe: [] as Array<Record<string, unknown>>,
+  invii: [] as string[],
+  falliscono: new Set<string>(),
+}));
+
+vi.mock('@/lib/api/middleware', () => ({ withCronAuth: (h: (req: unknown) => unknown) => (req: unknown) => h(req) }));
+vi.mock('@/lib/logger', () => ({ logger: { error: vi.fn(), warn: vi.fn(), info: vi.fn() } }));
+vi.mock('@/lib/push/send', () => ({
+  isPushConfigured: () => true,
+  iscrizioniPerUtenti: async (_s: unknown, ids: string[]) => new Map(ids.map((u) => [u, [{ id: `s-${u}` }]])),
+  sendPushToUser: async (_s: unknown, _userId: string, payload: { title: string }) => {
+    await new Promise((r) => setImmediate(r));
+    if (db.falliscono.has(payload.title)) throw new Error('servizio push giù');
+    db.invii.push(payload.title);
+    return { delivered: 1, total: 1 };
+  },
+}));
+vi.mock('@/lib/supabase/server', () => {
+  const ATTESA = new Set(['promo', 'group', 'newsletter']);
+  const righe = () => db.righe as unknown as Riga[];
+  const libera = (r: Riga, adesso: number) =>
+    r.pushed_at === null && (r.push_claimed_at === null || Date.parse(r.push_claimed_at) < adesso - 10 * 60_000);
+  return {
+    getAdminSupabase: () => ({
+      rpc: async (nome: string, a: { p_since?: string; p_max?: number }) => {
+        if (nome === 'vuole_notifica') return { data: true, error: null };
+        if (nome !== 'claim_pending_push') return { data: null, error: { message: `funzione ${nome} sconosciuta` } };
+        // Atomica: scelta e presa senza cedere il passo a nessuno.
+        const adesso = Date.now();
+        const prese = righe()
+          .filter((r) => libera(r, adesso) && r.created_at >= String(a.p_since))
+          .sort((x, y) => Number(ATTESA.has(x.category)) - Number(ATTESA.has(y.category)) || x.created_at.localeCompare(y.created_at))
+          .slice(0, a.p_max ?? 100);
+        for (const r of prese) r.push_claimed_at = new Date(adesso).toISOString();
+        return { data: prese.map(({ id, user_id, title, body, link, category }) => ({ id, user_id, title, body, link, category })), error: null };
+      },
+      from: () => {
+        const q: { valori: Partial<Riga> | null; tetto: number } = { valori: null, tetto: 100 };
+        const b: Record<string, unknown> = {};
+        const passa = () => b;
