+ * negozio: un negozio con promozioni spente e una promozione non letta vedeva il numero acceso e la
+ * pagina vuota. Qui si montano la pagina vera, il conteggio vero e il pannello negozio vero, e le
+ * loro letture girano contro un database finto che applica davvero i filtri.
+ */
+import { describe, it, expect, beforeEach, afterEach } from 'vitest';
+import { monta } from './aiuti/monta-componente';
+import { accendi, attendi } from './aiuti/schermo';
+
+const globali = globalThis as Record<string, unknown>;
+type Riga = Record<string, unknown>;
+
+/** Un PostgREST in miniatura: eq, neq, order, limit e il conteggio esatto, applicati alle righe. */
+function databaseFinto(tabelle: Record<string, Riga[]>, guasti: { profiles?: boolean } = {}) {
+  return {
+    from(tavola: string) {
+      const filtri: Array<(r: Riga) => boolean> = [];
+      let conta = false;
+      let tetto = Infinity;
+      let ordine: [string, boolean] | null = null;
+      const righe = () => {
+        const tutte = (tabelle[tavola] ?? []).filter((r) => filtri.every((f) => f(r)));
+        if (ordine) {
+          const [col, su] = ordine;
+          tutte.sort((a, b) => (String(a[col]) < String(b[col]) ? -1 : String(a[col]) > String(b[col]) ? 1 : 0) * (su ? 1 : -1));
+        }
+        return tutte.slice(0, tetto);
+      };
+      const guasto = tavola === 'profiles' && guasti.profiles ? { message: 'permission denied for table profiles' } : null;
+      const c: Record<string, unknown> = {
+        select: (_colonne: string, opz?: { count?: string; head?: boolean }) => { conta = opz?.count === 'exact'; return c; },
+        eq: (col: string, v: unknown) => { filtri.push((r) => r[col] === v); return c; },
+        neq: (col: string, v: unknown) => { filtri.push((r) => r[col] !== v); return c; },
+        in: (col: string, v: unknown[]) => { filtri.push((r) => v.includes(r[col])); return c; },
+        order: (col: string, o?: { ascending?: boolean }) => { ordine = [col, o?.ascending ?? true]; return c; },
+        limit: (n: number) => { tetto = n; return c; },
+        maybeSingle: async () => (guasto ? { data: null, error: guasto } : { data: righe()[0] ?? null, error: null }),
+        then: (ok: (x: unknown) => unknown, ko?: (e: unknown) => unknown) =>
+          Promise.resolve(
+            guasto ? { data: null, count: null, error: guasto }
+              : conta ? { data: null, count: righe().length, error: null } : { data: righe(), error: null },
+          ).then(ok, ko),
+      };
+      return c;
+    },
+  };
+}
+
+const NOTIFICHE: Riga[] = [
