@@ -0,0 +1,44 @@
+import { describe, it, expect } from 'vitest';
+import { readFileSync } from 'node:fs';
+import { join } from 'node:path';
+
+/**
+ * R33-009 — le due famiglie principali scaricano solo il dritto e con preload; il corsivo vero sta in
+ * due istanze a parte, senza preload, e le regole CSS lo usano: il browser scarica il file solo se in
+ * pagina c'è testo in corsivo.
+ */
+const root = process.cwd();
+const layout = readFileSync(join(root, 'app', 'layout.tsx'), 'utf8');
+const css = readFileSync(join(root, 'app', 'globals.css'), 'utf8');
+
+function istanza(nome: string, variabile: string): string {
+  const re = new RegExp(`${nome}\\(\\{[^}]*variable:\\s*'${variabile}'[^}]*\\}\\)`);
+  const m = layout.match(re);
+  expect(m, `${nome} con ${variabile}`).not.toBeNull();
+  return m![0];
+}
+
+describe('R33-009 — corsivo a richiesta', () => {
+  it('Inter e Fraunces principali: solo dritto, preload acceso', () => {
+    for (const [n, v] of [['Inter', '--font-inter'], ['Fraunces', '--font-serif']]) {
+      const o = istanza(n, v);
+      expect(o).toMatch(/style:\s*\['normal'\]/);
+      expect(o).not.toMatch(/preload:\s*false/);
+    }
+  });
+
+  it('due istanze del solo corsivo, senza preload, con le loro variabili sull\'<html>', () => {
+    for (const [n, v] of [['Inter', '--font-inter-italic'], ['Fraunces', '--font-serif-italic']]) {
+      const o = istanza(n, v);
+      expect(o).toMatch(/style:\s*\['italic'\]/);
+      expect(o).toMatch(/preload:\s*false/);
+    }
+    expect(layout).toMatch(/className=\{`[^`]*\$\{interCorsivo\.variable\}[^`]*\$\{frauncesCorsivo\.variable\}/);
+  });
+
+  it('il CSS manda il corsivo sulle due variabili, Fraunces dentro titoli e serif', () => {
+    expect(css).toMatch(/\.italic,\s*em,\s*i\s*\{\s*font-family:\s*var\(--font-inter-italic\),\s*var\(--font-sans\)/);
+    expect(css).toMatch(/font-family:\s*var\(--font-serif-italic\),\s*var\(--font-serif\)/);
+    expect(css).toMatch(/:is\(h1, h2, h3, \.font-serif, \.font-serif-display, \.font-display\) :is\(\.italic, em, i\)/);
+  });
+});
