+/** R33-016 — L'email al cliente del reso chiuso senza rimborso, col motivo del negozio. */
+function emailDelResoChiusoSenzaRimborso(orderId: string, nota: string | null) {
+  const numero = `#${orderId.slice(0, 8)}`;
+  const link = `${env.appUrl().replace(/\/$/, '')}/orders/${orderId}`;
