+    html: `${righe.map((r) => `<p style="margin:0 0 12px;line-height:1.6">${escapeHtml(r)}</p>`).join('')}` +
+      `<p style="margin:24px 0"><a href="${escapeHtml(link)}">Apri l'ordine</a></p>`,
+    text: `${righe.join(' ')} ${link}`,
+  };
